import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;

import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.FlatMapFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.common.typeinfo.TypeHint;
import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.sink.SinkFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedWriter;
import java.io.FileWriter;
import java.time.Duration;

public class LongestSessionPerJob extends AppBase {

    /** 10 minutes in microseconds. */
    private static final long SESSION_GAP_US = 10L * 60L * 1_000_000L;

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        final String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        // ---- Task-event stream: keep only SUBMIT events ----
        DataStream<TaskEvent> taskStream = env
                .addSource(taskSourceOrTest(new CsvFileSource<>(taskInput, TaskEvent::fromCSV)),
                        TypeInformation.of(TaskEvent.class))
                .flatMap((FlatMapFunction<TaskEvent, TaskEvent>) (e, out) -> {
                    if (e.eventType == TaskEvent.SUBMIT) out.collect(e);
                })
                .returns(TypeInformation.of(TaskEvent.class))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(Duration.ZERO)
                                .withTimestampAssigner((ev, ts) -> ev.timestamp));

        // ---- Job-event stream: keep only FINISH events ----
        DataStream<JobEvent> jobStream = env
                .addSource(jobSourceOrTest(new CsvFileSource<>(jobInput, JobEvent::fromCSV)),
                        TypeInformation.of(JobEvent.class))
                .flatMap((FlatMapFunction<JobEvent, JobEvent>) (e, out) -> {
                    if (e.eventType == JobEvent.FINISH) out.collect(e);
                })
                .returns(TypeInformation.of(JobEvent.class))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forBoundedOutOfOrderness(Duration.ZERO)
                                .withTimestampAssigner((ev, ts) -> ev.timestamp));

        // ---- Compute longest stage per job ----
        DataStream<Tuple2<Long, Long>> result = taskStream
                .keyBy(e -> e.jobId)
                .connect(jobStream.keyBy(e -> e.jobId))
                .process(new LongestStageFn())
                .returns(TypeInformation.of(new TypeHint<Tuple2<Long, Long>>() {}));

        @SuppressWarnings("unchecked")
        SinkFunction<Tuple2<Long, Long>> sink =
                (SinkFunction<Tuple2<Long, Long>>) sinkOrTest(new FileTupleSink(outputPath));
        result.addSink(sink);

        env.execute("LongestSessionPerJob");
    }

    /**
     * Per-job process function. Tracks the current open stage (count + last submit time)
     * and the maximum stage size seen so far. Emits the result once the job's FINISH
     * event has been observed and event time has advanced past it (guaranteeing that
     * all task SUBMIT events for the job have been processed).
     */
    public static class LongestStageFn
            extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, Tuple2<Long, Long>> {

        private transient ValueState<Long> currentCount;
        private transient ValueState<Long> lastSubmit;
        private transient ValueState<Long> maxCount;
        private transient ValueState<Boolean> emitted;

        @Override
        public void open(Configuration parameters) {
            currentCount = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("currentCount", Long.class));
            lastSubmit = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("lastSubmit", Long.class));
            maxCount = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("maxCount", Long.class));
            emitted = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("emitted", Boolean.class));
        }

        @Override
        public void processElement1(TaskEvent evt, Context ctx,
                                    Collector<Tuple2<Long, Long>> out) throws Exception {
            Long last = lastSubmit.value();
            Long cur = currentCount.value();
            Long max = maxCount.value();
            if (max == null) max = 0L;

            if (last == null || evt.timestamp - last > SESSION_GAP_US) {
                // Close previous stage, if any.
                if (cur != null && cur > max) max = cur;
                cur = 1L;
            } else {
                cur = (cur == null ? 0L : cur) + 1L;
            }
            currentCount.update(cur);
            lastSubmit.update(evt.timestamp);
            maxCount.update(max);
        }

        @Override
        public void processElement2(JobEvent evt, Context ctx,
                                    Collector<Tuple2<Long, Long>> out) throws Exception {
            // Defer emission until watermark passes the finish timestamp so we know
            // all earlier SUBMIT events have been processed.
            ctx.timerService().registerEventTimeTimer(evt.timestamp);
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx,
                            Collector<Tuple2<Long, Long>> out) throws Exception {
            Boolean already = emitted.value();
            if (already != null && already) return;

            Long cur = currentCount.value();
            Long max = maxCount.value();
            if (max == null) max = 0L;
            if (cur != null && cur > max) max = cur;

            out.collect(Tuple2.of(ctx.getCurrentKey(), max));
            emitted.update(Boolean.TRUE);
        }
    }

    /**
     * Simple source that reads a single (optionally gzipped) CSV file and emits parsed
     * records. Flink's FileSystem transparently handles .gz decoding when the file is
     * accessed via readTextFile; here we replicate the same behaviour with a small
     * source so that we can also plug in the test-injected source cleanly.
     */
    public static class CsvFileSource<T>
            extends org.apache.flink.streaming.api.functions.source.RichSourceFunction<T> {

        private final String path;
        private final Parser<T> parser;
        private volatile boolean running = true;

        public CsvFileSource(String path, Parser<T> parser) {
            this.path = path;
            this.parser = parser;
        }

        @Override
        public void run(SourceContext<T> ctx) throws Exception {
            java.io.InputStream in = new java.io.FileInputStream(path);
            if (path.endsWith(".gz")) {
                in = new java.util.zip.GZIPInputStream(in);
            }
            try (java.io.BufferedReader br = new java.io.BufferedReader(
                    new java.io.InputStreamReader(in, java.nio.charset.StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    if (line.isEmpty()) continue;
                    ctx.collect(parser.parse(line));
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    @FunctionalInterface
    public interface Parser<T> extends java.io.Serializable {
        T parse(String line);
    }

    /** Sink that appends each tuple as a line to a local file. */
    public static class FileTupleSink implements SinkFunction<Tuple2<Long, Long>> {
        private final String path;
        private transient BufferedWriter writer;
        private transient boolean truncated;

        public FileTupleSink(String path) {
            this.path = path;
        }

        @Override
        public synchronized void invoke(Tuple2<Long, Long> value, Context context) throws Exception {
            if (writer == null) {
                writer = new BufferedWriter(new FileWriter(path, truncated));
                truncated = true;
            }
            writer.write("(" + value.f0 + "," + value.f1 + ")");
            writer.newLine();
            writer.flush();
        }
    }
}
